import React, { useState, useEffect } from "react";
import * as XLSX from "xlsx";
import AWS from "aws-sdk";
import './styles.css';
import { gapi } from 'gapi-script';
import credentials from './credentials.json'; // Ensure this file exists locally

// Configure Wasabi (S3-compatible storage)
AWS.config.update({
  accessKeyId: '3MF2DSVWVGOI3S47VKY2',
  secretAccessKey: '65GzKkrWaBMgPFrMBtQrPEeGYAHIFMMTCj29QiqB',
  region: "ca-central-1",
});

const s3 = new AWS.S3({
  endpoint: 'https://s3.ca-central-1.wasabisys.com',
  s3ForcePathStyle: true,
});

const CLIENT_ID = '992160036280-eqdq9aivb6ge2k7m4hbj45drnpsuj8mf.apps.googleusercontent.com';
const API_KEY = 'AIzaSyCsYLLOsbEVnflZYmTueEXcJBaeorWdJ6w';
const SCOPES = 'https://www.googleapis.com/auth/spreadsheets';
const SHEET_ID = '1_4kXYSy8gwky5Xx4DCt6BxLM8QKBOfIjNfUgg5UpeoM';

const UploadForm = () => {
  const [fileType, setFileType] = useState("");
  const [formData, setFormData] = useState({});
  
  useEffect(() => {
    function start() {
      gapi.client.init({
        apiKey: API_KEY,
        clientId: CLIENT_ID,
        scope: SCOPES,
        discoveryDocs: ["https://sheets.googleapis.com/$discovery/rest?version=v4"],
      });
    }

    gapi.load('client:auth2', start);
  }, []);

  const handleChange2 = (e) => {
    const { name, value, type, files } = e.target;

    if (type === "file") {
      const newFiles = Array.from(files);
      setFormData((prevData) => {
        const existingFiles = Array.isArray(prevData.files) ? prevData.files : [];
        const updatedFiles = existingFiles.filter((file) =>
          !newFiles.some((newFile) => newFile.name === file.name)
        );
        return {
          ...prevData,
          files: [...updatedFiles, ...newFiles],
        };
      });
    } else {
      setFormData((prevData) => ({
        ...prevData,
        [name]: value,
      }));
    }
  };

  const uploadToWasabi2 = async (file, bin) => {
    try {
      const fileName = `${bin}/${file.name}`;
      const uploadParams = {
        Bucket: "may2025",
        Key: fileName,
        Body: file,
        ACL: "public-read",
        ContentType: file.type,
      };

      await s3.upload(uploadParams).promise();

      const signedUrlParams = {
        Bucket: "may2025",
        Key: fileName,
        Expires: 60 * 60 * 48,
      };

      const preSignedUrl = s3.getSignedUrl("getObject", signedUrlParams);
      return { fileName, url: preSignedUrl };
    } catch (error) {
      console.error("Upload error:", error);
      return null;
    }
  };

  const appendToGoogleSheet = async (rows) => {
    try {
      await gapi.auth2.getAuthInstance().signIn(); // Trigger sign in
      const sheets = gapi.client.sheets;

      await sheets.spreadsheets.values.append({
        spreadsheetId: SHEET_ID,
        range: 'Sheet1!A:F',
        valueInputOption: 'USER_ENTERED',
        resource: {
          values: rows,
        },
      });
    } catch (error) {
      console.error("Sheet append error:", error);
      throw error;
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const files = formData.files || [];
    if (!formData.bin || files.length === 0) {
      alert("Please provide BIN and upload at least one file.");
      return;
    }

    const uploadedUrls = await Promise.all(
      files.map((file) => uploadToWasabi2(file, formData.bin))
    );

    const wasabiUrls = uploadedUrls.filter(Boolean);

    const rows = wasabiUrls.map(({ fileName, url }) => [
      new Date().toISOString(),
      fileType,
      formData.fileStatus || "",
      formData.bookDetails || "",
      formData.bin || "",
      url,
    ]);

    try {
      await appendToGoogleSheet(rows);
      alert("Files uploaded and data appended to Google Sheet!");
      setFormData({});
      setFileType("");
      e.target.reset();
    } catch (error) {
      alert("Failed to upload to Google Sheets.");
    }
  };

  const renderFileFields = () => {
    const sections = {
      coverFile: [
        "Book Cover PDF",
        "Book Cover PSD",
        "Cover Front Thumbnail",
        "Cover Back Thumbnail",
        "Book Cover Inside PDF (if applicable)",
        "Book Cover Inside PSD (if applicable)",
        "Cover Mockups",
        "Mockup 1",
        "Mockup 2",
        "Mockup 3",
        "Cover for GDP - PDF",
        "Cover for GDP - PSD",
      ],
      interiorFile: [
        "Upload PDF File",
        "Upload Open File (Indesign/Word/PageMaker/.pages)",
        "Interior File for GDP",
      ],
      epubFile: ["Upload EPUB file", "Upload KPF file"],
      posterFile: ["Upload the poster PDF"],
      globalFile: [
        "Cover for GDP - PDF",
        "Cover for GDP - PSD",
        "Revised Mockup",
        "Interior File for GDP",
      ],
    };

    return (
      <div className="space-y-4">
        {sections[fileType]?.map((field, index) => (
          <label key={index} className="block">
            <span className="text-gray-700">{field}:</span>
            <input
              type="file"
              name={field}
              onChange={handleChange2}
              className="block w-full border border-gray-300 rounded-md p-2 mt-1"
            />
          </label>
        ))}
      </div>
    );
  };

  return (
    <div className="center-box">
      <div className="max-w-xl mx-auto bg-white p-6 shadow-lg rounded-lg">
        <h2 className="text-xl font-semibold text-gray-800 mb-4">Final Files Submission</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <label className="block">
            <span className="text-gray-700">File Type:</span>
            <select name="fileType" onChange={(e) => setFileType(e.target.value)} className="value">
              <option value="">-- Select --</option>
              <option value="coverFile">Cover File</option>
              <option value="interiorFile">Interior File</option>
              <option value="epubFile">ePub</option>
              <option value="posterFile">Poster</option>
              <option value="globalFile">Only Global - Cover and Interior</option>
            </select>
          </label>

          {fileType && (
            <div className="space-y-4 border-t pt-4">
              <label className="block">
                <span className="text-gray-700">File Status:</span>
                <select name="fileStatus" onChange={handleChange2} className="value">
                  <option value="new">New</option>
                  <option value="updated">Updated Version</option>
                </select>
              </label>

              <label className="block">
                <span className="text-gray-700">Book Title_Author Name_ISBN:</span>
                <input type="text" name="bookDetails" onChange={handleChange2} className="value" />
              </label>

              <label className="block">
                <span className="text-gray-700">BIN:</span>
                <input type="text" name="bin" onChange={handleChange2} className="value" />
              </label>

              {renderFileFields()}
            </div>
          )}

          <button type="submit" className="bg-blue-500 text-white px-4 py-2 rounded-md hover:bg-blue-600">
            Submit
          </button>
        </form>
      </div>
    </div>
  );
};

export default UploadForm;